# Keys: (pfad_oder_basename, "Feld#c:CODE") bzw. "Feld#r:ZEILE" (Quellzeile ohne Code).

DE_REST_B3 = {
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101_0'): 'Ho ho...\nAuf welche Weise steigt ihr an diesen Ort hinauf?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101_1'): 'Hört mich, ungebetene Gäste.\nWenn ihr jene Brücke überquert, wird euer\nHeimweg für immer verwirkt sein.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101_2'): 'Kehrt um... Kehrt um...',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101_3'): 'Kehrt um...\n*hust* Ihr wisst doch, dass ich rede, oder?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101_4'): 'Dort liegt das Erhabene Reich... das Reich\nder Götter. Kein Ort für Menschen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101_5'): 'Oi. Welcher Teil von „Kehrt um" entgeht euch?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_0'): 'Ha! Ich habe euch endlich gefunden.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_1'): 'Ich hatte keine Ahnung, dass so eine gewaltige Brücke\nauf diesem Berg liegt.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_10'): 'Das lasse ich nicht zu!\nKehre sofort zurück, Prinzessin!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_11'): 'Was zum...? Was geht hier vor?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_12'): 'Whoa!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_13'): 'Hm? Oh, bitte, fahrt fort.\nIhr müsst mir wegen mir nicht unterbrechen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_14'): 'Trotzdem, wie faszinierend!\nSeid ihr Menschen? Seid ihr es, oder?!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_15'): 'Sofort beim Betreten des Erhabenen\nReichs die Kreuze kreuzen... Was für eine barbarische Schau.\nWeiter dann! Macht weiter!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_16'): 'Der Zehnttag ist so langweilig. Alles, was zu tun ist,\nist trinken, bis ich dran bin.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_17'): 'Aber heute hat mein kleiner Ausflug mit\neiner unerwarteten Begegnung belohnt. Heehee...',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_18'): 'Meine Prinzessin, du darfst dich mit solch--',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_19'): 'Du brauchst dir keine Sorgen zu machen.\nIch bin bald zurück. *Schluck*',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_2'): 'Es wird Zeit zu zahlen.\nDieses Mal entkommst du mir nicht, Katsura.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_20'): 'Oho... Ein ziemlich luxuriöser Auftritt.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_21'): 'Oooh, du bist für einen Racker ziemlich scharfsichtig!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_22'): 'Prächtig, oder? Der Gipfel der Eleganz!\nEr zeigt meinen Status herrlich,\nmeinst du nicht?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_23'): 'Ugh, du stinkst nach Sake!\nIch hielt dich für ein Kind!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_24'): 'Mrrrgh, wie wagst du das!\nIch bin ein kerngesunder Erwachsener!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_25'): 'Gaaah!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_26'): 'Puh... Der Stich dieser schrecklichen Bemerkung\nhat mich sofort nüchtern gemacht.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_27'): 'Ich schätze, ich kehre zum Bankett zurück und\nmich der Freude der Trunkenheit wieder zuwende.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_28'): 'Kinder der Menschen, vor euch liegt das Reich der\nGötter. Kehrt um, bevor die Brücke verschwindet.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_29'): 'Tut ihr das nicht, kann für eure Sicherheit\nnicht eingestanden werden... so sagen sie.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_3'): 'Ishimaru... Warum bist du uns so weit nachgeeilt?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_30'): 'Hm, hm, hmmm...!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_31'): 'Dieses Kind hat unglaubliche Kraft.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_32'): 'Sie sprach von einem Bankett. Wenn wir ihr folgen,\nfinden wir vielleicht etwas zu essen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_4'): 'Einem Tölpel wie dir ist das wohl nicht klar,\naber auch wir sind am Ende unseres Lateins.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_5'): 'Ich kann diese Kinder nicht gehen lassen,\nund du, Verräter... du musst sterben.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_6'): 'Dann werde ich mich fassen, wenn schon!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_7'): 'Könntest du noch jämmerlicher wirken?\nIch kann nicht glauben, dass du ein Samurai bist.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_8'): 'Egal. Stirb einfach!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:98000101b_9'): 'Was? Prinzessin!\nWas machst du an einem Ort wie diesem?!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_0'): 'Das ist...',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_1'): 'Kinta... Bist das du, Kinta?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_10'): 'UND DANN wurden wir jede Nacht darüber belehrt,\ndafür dankbar zu sein!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_11'): 'Ich weiß, du hast versucht, es richtig zu machen, aber wir\nkonnten es nicht ertragen, von denselben Mönchen\nbelehrt zu werden, die uns im nächsten Moment schlugen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_12'): 'Also haben wir die Verluste begrenzt und sind weggelaufen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_13'): 'Wir liefen und liefen... und taten alles, um zu überleben.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_14'): 'Wie schändlich... Ich muss blind gewesen sein,\nsolche Verwahrlosung in meinem Tempel zu übersehen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_15'): 'Es tut mir so, so leid, Kinta.\nWirklich... ich bitte um deine Verzeihung.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_16'): 'Dieser Tempel brauchte eine Umwälzung, um dem\nkriegerischen Weltgeschehen außerhalb seiner Mauern zu begegnen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_17'): 'Hätten wir Herzen und Körper nicht gestärkt,\nwären wir nicht fähig gewesen, unser Heiligtum zu\nverteidigen. So war das grausame Zeitalter, in dem wir lebten.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_18'): 'Der Tempel war das letzte Heiligtum für die\nMenschen jenes Landes. Wir mussten ihn um jeden\nPreis befestigen.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_19'): 'Ich vertraute auf unseren guten Namen, um mit den\nStarken zu verhandeln. Jetzt ist jeder Prestige, den wir\nje hatten, Staub im Wind.\n',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_2'): 'Ich kenne diese Stimme.\nDu bist... der Obermönch aus jenem Tempel, was?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_20'): 'Aber welchen Nutzen hat Stärke ohne\nIntegrität? Meine Unbesonnenheit hat die Sicherheit\nder Kinder in meiner Obhut gefährdet.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_21'): 'Wie zynisch.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_22'): 'Kinta... Hasst du mich?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_23'): 'Natürlich tue ich das.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_24'): 'Aber nicht nur dich.\nIch hasse alle im Niedrigen Reich.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_25'): 'Die Ausländer, die mein Dorf niederbrannten...\nmein jämmerlicher Vater, der nicht Mutter\nund Schwester schützen konnte...',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_26'): 'Und mich selbst auch.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_27'): 'Oh, Kinta. Mein lieber Kinta.\nHör zu...',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_28'): 'Wha--?! Der Nebel wird dichter.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_29'): 'Whoa!',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_3'): 'Es ist schon einige Zeit her, mein Junge.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_4'): 'Du bist, äh... körperlicher, als ich es\nin Erinnerung hatte. Hat dieser marode alte Körper\nendlich nachgegeben und dich ins Erhabene Reich geschickt?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_5'): 'Ho ho... Oder aus einer anderen Perspektive\nbedeutet die Tatsache, dass du EINEN Körper hast,\ndass du trotzdem hier noch lebst.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_6'): 'Das ist gut. Ich machte mir große Sorgen,\ndass du deinen letzten Atemzug in einer\nabgelegenen Gosse gezogen hast.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_7'): 'Nun denn. Würdest du einem alten Mann gefallen\nund erklären, warum du den Tempel verlassen hast?',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_8'): 'Weißt du... Es war nicht so, dass wir ein Problem\nmit der Arbeit hatten. Wenn das alles gewesen wäre,\nwären wir nicht in die Berge gerannt.',
    ('Text/Event/Event/Ukihashi.csvtxt', 'English#c:SubEvent_Kinta_Osho_9'): 'Aber wir hatten die Nase voll, jeden verdammten Tag\nvon diesen sogenannten „Mönchen" verprügelt zu werden.\nSie haben uns ordentlich dringenommen.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_0'): '...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_1'): 'Sag mal, Tama...\nglaubst du, ich kann Omizuchi so wie ich bin besiegen?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_10'): 'Die Insel, auf der sich deine Eltern trafen?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_11'): 'Die Insel, auf der du mit den Kindern der\nMenschen gearbeitet und gelebt hast?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_12'): 'Natürlich.\nAber was können wir allein tun?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_13'): 'Wir sprachen von der Macht, die in deinem\ngöttlichen Gewand ruht. Solltest du sie begehren,\nist ein angemessenes Opfer erforderlich.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_14'): 'In einfacheren Worten:\nDu kannst Macht erlangen, wenn du einen Preis zahlst.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_15'): 'Was willst du damit sagen?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_16'): 'Jetzt ist die Zeit, die verborgene Macht in deinem\nheiligen Erbstück zu wecken, meine Herrin.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_17'): 'Der wahre Name jenes Gewands ist\n„der Schal, der die Reiche durchquert."',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_18'): 'Ich weiß nicht, wer es geschaffen hat oder wozu,\nund ich weiß auch nicht, was geschieht, wenn du\nsein wahres Potenzial entfaltest.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_19'): 'Egal wie entschlossen du bist, Omizuchi die Stirn\nzu bieten -- es bedeutet nichts, wenn er in ein anderes\nReich gesandt wird.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_2'): 'Du bist wahrlich stark geworden, an Geist\nund Körper.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_20'): 'Und dann...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_21'): 'Dann... was?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_22'): 'Ich, Tama, die heilige Klinge des Hoshidama,\nwirde mich selbst schmelzen und zu einem neuen\nAckerwerkzeug für dich umgeformt werden.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_23'): 'Wenn du ein Ackerwerkzeug führest, das die Macht\ndes heiligen Schwertes in sich trägst, könntest du\nsogar Omizuchis fürchterliche Haut durchdringen.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_24'): 'Nein, ICH werde Omizuchi treffen,\nselbst wenn es mich alles kostet!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_25'): 'Du wirst „schmelzen und neu geformt"?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_26'): 'Wie kannst du das sagen, Tama?!\nWenn du das tust, wirst du sicherlich...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_27'): 'Meine Seele residiert nun nur noch im Griff des\nSchwertes und schenkt mir diese körperliche Form.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_28'): 'Wenn ich aufgelöst und mit neuem Eisen neu geformt\nwerde, werde ich als heiliges Schwert wiedergeboren,\naber ich verliere dabei wahrscheinlich meine Seele.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_29'): 'Nein... Warum stellst du mich vor solch eine\nentsetzliche Entscheidung?!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_3'): 'Du bist jetzt wohl stärker als die meisten Götter in\nder Hauptstadt. Für mich gibt es kein\ngrößeres Glück.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_30'): 'Du sagst mir, ich soll dich als Opfer bringen?\nDich, der du mich ganz allein großgezogen hast?!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_31'): 'Du bist sehr gütig, Prinzessin.\nIch bin solcher Empfindung nicht würdig.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_32'): 'Wahrhaftig, mein Herz überquillt vor Freude.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_33'): 'Jedoch... Am Ende bin ich nur ein Schwert.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_34'): 'Ich schlug zahllose Feinde in den\ngeübten Händen Lord Takeribis nieder, also kann ich,\nwenn ich jene Pflicht einst als dein Schwert erfülle...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_35'): '...dann werde ich über dieses Reich hinausgehen,\nfrei von irdischen Sorgen.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_36'): 'Nein... Nein, absolut nicht!\nIch könnte so etwas nicht ertragen!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_37'): 'Für einen so einsamen Pfad würdest du mich setzen...\nEin Sieg ohne dich wäre hohl!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_38'): 'Du musst jenem unverschämten Omizuchi den\nWillen zeigen, den die Götter Yanatos besitzen!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_39'): 'Das ist lächerlich! Das lasse ich nicht zu!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_4'): 'Jedoch, leider...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_40'): 'Dein Opfer sichert unseren Triumph nicht!\nWir könnten am Ende trotzdem alle sterben.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_41'): 'Ja... Es ist wie Kinta sagte.\n„Es ist nichts wert, wenn wir sterben."',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_42'): 'Hör mich an, Tama. Sprich nie wieder davon.\nDas ist ein Befehl von deiner Herrin!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_43'): 'Prinzessin...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_44'): 'Schlamm... Nein, Asche, gemischt mit Regen?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_45'): 'Wie auch immer, kehren wir vorerst nach Hause.\nIch mache mir Sorgen um die anderen und unsere Felder.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_5'): 'Du hast die Höhe deines Vaters noch nicht erreicht,\nund Omizuchi scheint jetzt viel mächtiger\nals in der Vergangenheit zu sein.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_6'): 'Es würde die volle Macht jedes Gottes in\nder Hauptstadt erfordern, ihn zu beugen.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_7'): 'Wenn doch nur Lord Takeribi und Lady Toyohana\nzurückkehren würden...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_8'): 'Ja... Ich schätze, du hast recht.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:05000601_9'): 'Prinzessin, möchtest du diese Insel beschützen?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_0'): 'Sag mal, Tama...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_1'): 'Ishimaru war ein jämmerlicher Mensch, oder?',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_10'): 'Ich werde gegen Omizuchi kämpfen!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_11'): '...!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_12'): 'Tama... Nein, die Klinge des Hoshidama.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_13'): 'Leih mir deine Stärke!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_14'): 'Prinzessin...!',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_15'): 'Du hast... wohl gesprochen.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_16'): 'Ich... bitte aufrichtig um Verzeihung.\nIch kann keinen anderen Weg finden.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_17'): 'Wenn du dich so entschieden hast,\ndann hat das an sich schon einen Sinn.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_18'): 'Ich werde nie vergessen, was du für mich getan hast.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_19'): 'Ich war gesegnet, zwei großartige Herren zu haben.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_2'): 'Ja...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_20'): 'Auch wenn meine Form sich ändert, werde ich stets\nan deiner Seite sein. Lass uns gemeinsam voranschreiten.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_21'): 'Ja... aber zuerst wartet das Homusubi-Gespenst.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_22'): 'Bitte bleib noch ein kleines Weilchen so, wie du bist.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_3'): 'Ich könnte genau wie er enden, wenn ich alle verliere.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_4'): '...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_5'): 'Ich verabscheue den Gedanken, sie zu verlieren.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_6'): 'Ich möchte diese Insel beschützen.\nJe mehr Zeit vergeht, desto stärker wird dieser Wunsch.',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_7'): '...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_8'): 'Deshalb...',
    ('Text/Event/Event/WayBack.csvtxt', 'English#c:07000501_9'): 'Ich werde...!',
}

